#[test]
fn new_and_convert_to_match_named_methods() {
    let v = 1234.5;
    assert_eq!(
        ElectricCurrentDensity::new(v, ElectricCurrentDensityUnit::AmperePerSquareMeter),
        ElectricCurrentDensity::from_amperes_per_square_meter(v)
    );
    assert_eq!(
        ElectricCurrentDensity::from_base(v)
            .convert_to(ElectricCurrentDensityUnit::AmperePerSquareMeter),
        ElectricCurrentDensity::from_base(v).as_amperes_per_square_meter()
    );
    assert_eq!(
        ElectricCurrentDensity::new(v, ElectricCurrentDensityUnit::AmperePerSquareInch),
        ElectricCurrentDensity::from_amperes_per_square_inch(v)
    );
    assert_eq!(
        ElectricCurrentDensity::from_base(v)
            .convert_to(ElectricCurrentDensityUnit::AmperePerSquareInch),
        ElectricCurrentDensity::from_base(v).as_amperes_per_square_inch()
    );
    assert_eq!(
        ElectricCurrentDensity::new(v, ElectricCurrentDensityUnit::AmperePerSquareFoot),
        ElectricCurrentDensity::from_amperes_per_square_foot(v)
    );
    assert_eq!(
        ElectricCurrentDensity::from_base(v)
            .convert_to(ElectricCurrentDensityUnit::AmperePerSquareFoot),
        ElectricCurrentDensity::from_base(v).as_amperes_per_square_foot()
    );
}

#[test]
fn parse_every_abbreviation() {
    assert_eq!(
        "A/m²".parse::<ElectricCurrentDensityUnit>(),
        Ok(ElectricCurrentDensityUnit::AmperePerSquareMeter)
    );
    assert_eq!(
        format!("2.5 {}", "A/m²").parse::<ElectricCurrentDensity>(),
        Ok(ElectricCurrentDensity::new(
            2.5,
            ElectricCurrentDensityUnit::AmperePerSquareMeter
        ))
    );
    assert_eq!(
        "A/in²".parse::<ElectricCurrentDensityUnit>(),
        Ok(ElectricCurrentDensityUnit::AmperePerSquareInch)
    );
    assert_eq!(
        format!("2.5 {}", "A/in²").parse::<ElectricCurrentDensity>(),
        Ok(ElectricCurrentDensity::new(
            2.5,
            ElectricCurrentDensityUnit::AmperePerSquareInch
        ))
    );
    assert_eq!(
        "A/ft²".parse::<ElectricCurrentDensityUnit>(),
        Ok(ElectricCurrentDensityUnit::AmperePerSquareFoot)
    );
    assert_eq!(
        format!("2.5 {}", "A/ft²").parse::<ElectricCurrentDensity>(),
        Ok(ElectricCurrentDensity::new(
            2.5,
            ElectricCurrentDensityUnit::AmperePerSquareFoot
        ))
    );
    assert_eq!(
        "1 not-a-unit".parse::<ElectricCurrentDensity>(),
        Err(ParseError::UnknownUnit)
    );
}

